export const ALL_ASSETS = [
    ...SHOP_ASSETS,
    ...SPECIAL_FORM_ASSETS
];

export const STARTER_UNLOCKS = ["body-blue", "eyes-regular"];

export const TRAIT_DISCOVERY_POOL = SHOP_ASSETS.filter(asset => asset.price > 0 && asset.rarity !== "starter");

export function getAssetById(id) {
    return ALL_ASSETS.find(asset => asset.id === id) || null;
}

function frameUrl(basePath, index) {
    return basePath.replace("frame_00.png", `frame_${String(index).padStart(2, "0")}.png`);
}

export function preloadCatalog(scene) {
    for (const gem of Object.values(GEM_TYPES)) {
        for (let i = 0; i < gem.frames; i += 1) scene.load.image(`${gem.key}-${i}`, frameUrl(gem.framePath, i));
        scene.load.image(gem.key, gem.framePath);
    }

    const loadedSpinKeys = new Set();
    for (const spin of Object.values(BODY_SPIN_ASSETS)) {
        if (loadedSpinKeys.has(spin.key)) continue;
        loadedSpinKeys.add(spin.key);
        for (let i = 0; i < spin.frames; i += 1) scene.load.image(`${spin.key}-${i}`, frameUrl(spin.framePath, i));
    }

    for (let i = 0; i < ENEMY_DEATH_ASSET.frames; i += 1) scene.load.image(`${ENEMY_DEATH_ASSET.key}-${i}`, frameUrl(ENEMY_DEATH_ASSET.framePath, i));

    for (const mine of TANK_MINE_ASSETS) {
        for (let i = 0; i < mine.frames; i += 1) scene.load.image(`${mine.key}-${i}`, frameUrl(mine.framePath, i));
        scene.load.image(mine.key, mine.framePath);
    }

    for (const asset of ALL_ASSETS) {
        if (asset.frames && asset.framePath) {
            for (let i = 0; i < asset.frames; i += 1) scene.load.image(`${asset.key}-${i}`, frameUrl(asset.framePath, i));
        }
        scene.load.image(asset.key, asset.framePath || asset.path);
    }

    scene.load.image("tank-bg", "./assets/raw/Backgrounds/shallow1.png");
    scene.load.image("ocean-bg", "./assets/raw/Backgrounds/deep1.png");
    const tankEnemyAssets = [
        { key: "tank-enemy-jelly", frames: 4, framePath: "./assets/generated/tank-enemies/tank-enemy-jelly/frame_00.png" },
        { key: "tank-enemy-eel", frames: 12, framePath: "./assets/generated/tank-enemies/tank-enemy-eel/frame_00.png" },
        { key: "tank-enemy-fish", frames: 8, framePath: "./assets/generated/tank-enemies/tank-enemy-fish/frame_00.png" },
        { key: "tank-enemy-enemi1", frames: 8, framePath: "./assets/generated/tank-enemies/tank-enemy-enemi1/frame_00.png" },
        { key: "tank-enemy-enemi2", frames: 8, framePath: "./assets/generated/tank-enemies/tank-enemy-enemi2/frame_00.png" },
        { key: "tank-enemy-enemi3", frames: 8, framePath: "./assets/generated/tank-enemies/tank-enemy-enemi3/frame_00.png" },
        { key: "tank-enemy-enemi4", frames: 8, framePath: "./assets/generated/tank-enemies/tank-enemy-enemi4/frame_00.png" },
        { key: "tank-enemy-enemi5", frames: 8, framePath: "./assets/generated/tank-enemies/tank-enemy-enemi5/frame_00.png" },
        { key: "tank-enemy-enemi1112", frames: 3, framePath: "./assets/generated/tank-enemies/tank-enemy-enemi1112/frame_00.png" },
        { key: "tank-enemy-enemi112", frames: 8, framePath: "./assets/generated/tank-enemies/tank-enemy-enemi112/frame_00.png" },
        { key: "tank-enemy-enemi1132", frames: 8, framePath: "./assets/generated/tank-enemies/tank-enemy-enemi1132/frame_00.png" },
        { key: "tank-enemy-enemi1142", frames: 8, framePath: "./assets/generated/tank-enemies/tank-enemy-enemi1142/frame_00.png" },
        { key: "tank-enemy-narval", frames: 5, framePath: "./assets/generated/tank-enemies/tank-boss-enemynarval/frame_00.png" },
        { key: "tank-enemy-shark", frames: 4, framePath: "./assets/generated/tank-enemies/tank-boss-enemyshark/frame_00.png" },
        { key: "tank-enemy-whale", frames: 5, framePath: "./assets/generated/tank-enemies/tank-boss-enemywhale/frame_00.png" },

        { key: "tank-boss-blue-shark", frames: 4, framePath: "./assets/generated/tank-enemies/tank-boss-blue-shark/frame_00.png" },
        { key: "tank-boss-red-shark", frames: 12, framePath: "./assets/generated/tank-enemies/tank-boss-red-shark/frame_00.png" },
        { key: "tank-boss-mummy-shark", frames: 13, framePath: "./assets/generated/tank-enemies/tank-boss-mummy-shark/frame_00.png" },
        { key: "tank-boss-halloween-small-1", frames: 20, framePath: "./assets/generated/tank-enemies/tank-boss-halloween-small-1/frame_00.png" },
        { key: "tank-boss-halloween-small-2", frames: 16, framePath: "./assets/generated/tank-enemies/tank-boss-halloween-small-2/frame_00.png" }
    ];
    for (const enemy of tankEnemyAssets) {
        for (let i = 0; i < enemy.frames; i += 1) scene.load.image(`${enemy.key}-${i}`, frameUrl(enemy.framePath, i));
        scene.load.image(enemy.key, enemy.framePath);
    }
    scene.load.image("tank-bullet", "./assets/raw/Bullets/normal.gif");
    scene.load.image("tank-bullet-toxic", "./assets/raw/Bullets/toxic.gif");
    scene.load.image("tank-bullet-fire", "./assets/raw/Bullets/fire.gif");
    scene.load.image("tank-bullet-ice", "./assets/raw/Bullets/iceink.gif");
    scene.load.image("tank-bullet-electric", "./assets/raw/Bullets/electric.gif");
    scene.load.image("tank-bullet-ink", "./assets/raw/Bullets/inkbullet (1).gif");
}
